/**
 * Registered participants — every team that registered for Ghost Protocol CTF 2.0.
 *
 * Generated from the official registration sheet (Form Responses export).
 * Team names are reproduced exactly as submitted. Member names come from the
 * team-leader, member-2 and member-3 columns in that order.
 *
 * `status` encodes how far the team got:
 *   winner       — podium of the 12-hour on-ground finale
 *   qualified    — cleared the online qualifier and played the finale
 *   participated — registered and played the qualifier
 */

export type ParticipantStatus = 'winner' | 'qualified' | 'participated'

export type ParticipantTeam = {
  /** Registration ID issued to the team (may be missing for late additions). */
  id: string | null
  team: string
  members: string[]
  status: ParticipantStatus
  /** Finale podium position, present only for winners. */
  rank?: number | null
}

